     1→/**
     2→ * GEDCOM Data Mapper
     3→ * Bidirectional mapping between GEDCOM and Vamsa data models
     4→ */
     5→
     6→import type { GedcomFile } from "./types";
     7→import {
     8→  type MappingResult,
     9→  type MappingError,
    10→  type VamsaPerson,
    11→  type VamsaRelationship,
    12→  type GedcomIndividualData,
    13→  type GedcomFamilyData,
    14→  type MapOptions,
    15→  type ParsedName,
    16→} from "./mapper-types";
    17→import { GedcomParser } from "./parser";
    18→
    19→/**
    20→ * Generate a CUID-like ID for use in mapping operations
    21→ * Uses timestamp + random characters for collision-resistant IDs
    22→ */
    23→function generateId(): string {
    24→  const timestamp = Date.now().toString(36);
    25→  const randomPart = Math.random().toString(36).substring(2, 9);
    26→  return `c${timestamp}${randomPart}`;
    27→}
    28→
    29→export class GedcomMapper {
    30→  private parser: GedcomParser;
    31→
    32→  constructor() {
    33→    this.parser = new GedcomParser();
    34→  }
    35→
    36→  /**
    37→   * Convert parsed GEDCOM data to Vamsa data model
    38→   */
    39→  mapFromGedcom(gedcomFile: GedcomFile, options?: MapOptions): MappingResult {
    40→    const people: VamsaPerson[] = [];
    41→    const relationships: VamsaRelationship[] = [];
    42→    const errors: MappingError[] = [];
    43→    const warnings: string[] = [];
    44→
    45→    // 1. Validate GEDCOM structure
    46→    if (!options?.skipValidation) {
    47→      const validationErrors = this.parser.validate(gedcomFile);
    48→      for (const error of validationErrors) {
    49→        if (error.severity === "error") {
    50→          errors.push({
    51→            type: "invalid_format",
    52→            source: "INDI",
    53→            id: "unknown",
    54→            field: "structure",
    55→            message: error.message,
    56→          });
    57→        } else {
    58→          warnings.push(error.message);
    59→        }
    60→      }
    61→    }
    62→
    63→    // 2. Create ID mapping (GEDCOM xrefs -> Vamsa CUIDs)
    64→    const idMap = new Map<string, string>();
    65→    for (const individual of gedcomFile.individuals) {
    66→      if (individual.id) {
    67→        idMap.set(individual.id, generateId());
    68→      }
    69→    }
    70→
    71→    // 3. Map individuals (INDI -> Person)
    72→    for (const record of gedcomFile.individuals) {
    73→      if (!record.id) continue;
    74→
    75→      const parsed = this.parser.parseIndividual(record);
    76→      const vamsaId = idMap.get(parsed.id);
    77→
    78→      if (!vamsaId) {
    79→        errors.push({
    80→          type: "missing_data",
    81→          source: "INDI",
    82→          id: parsed.id,
    83→          field: "id",
    84→          message: `Failed to generate ID for individual ${parsed.id}`,
    85→        });
    86→        continue;
    87→      }
    88→
    89→      // Parse name
    90→      const primaryName = parsed.names[0];
    91→      const parsedName = primaryName
    92→        ? this.parseName(primaryName.full)
    93→        : { firstName: "Unknown", lastName: "Unknown" };
    94→
    95→      if (!parsedName.firstName) {
    96→        parsedName.firstName = "Unknown";
    97→      }
    98→      if (!parsedName.lastName) {
    99→        parsedName.lastName = "Unknown";
   100→      }
   101→
   102→      // Determine if person is living
   103→      const isLiving = !parsed.deathDate;
   104→
   105→      // Convert date strings to Date objects
   106→      const dateOfBirth = parsed.birthDate
   107→        ? this.parseISODate(parsed.birthDate)
   108→        : undefined;
   109→      const dateOfPassing = parsed.deathDate
   110→        ? this.parseISODate(parsed.deathDate)
   111→        : undefined;
   112→
   113→      // Map gender
   114→      const gender = this.unmapGender(parsed.sex);
   115→
   116→      const person: VamsaPerson = {
   117→        id: vamsaId,
   118→        firstName: parsedName.firstName,
   119→        lastName: parsedName.lastName,
   120→        dateOfBirth,
   121→        dateOfPassing,
   122→        birthPlace: parsed.birthPlace,
   123→        gender,
   124→        profession: parsed.occupation,
   125→        bio: parsed.notes.join("\n") || undefined,
   126→        isLiving,
   127→      };
   128→
   129→      people.push(person);
   130→    }
   131→
   132→    // 4. Map families (FAM -> Relationships)
   133→    for (const record of gedcomFile.families) {
   134→      if (!record.id) continue;
   135→
   136→      const parsed = this.parser.parseFamily(record);
   137→
   138→      // Create spouse relationships
   139→      if (parsed.husband && parsed.wife) {
   140→        const husbandId = idMap.get(parsed.husband);
   141→        const wifeId = idMap.get(parsed.wife);
   142→
   143→        if (!husbandId || !wifeId) {
   144→          if (!options?.ignoreMissingReferences) {
   145→            errors.push({
   146→              type: "broken_reference",
   147→              source: "FAM",
   148→              id: parsed.id,
   149→              field: "HUSB/WIFE",
   150→              message: `Broken spouse reference in family ${parsed.id}`,
   151→            });
   152→          }
   153→          continue;
   154→        }
   155→
   156→        const marriageDate = parsed.marriageDate
   157→          ? this.parseISODate(parsed.marriageDate)
   158→          : undefined;
   159→        const divorceDate = parsed.divorceDate
   160→          ? this.parseISODate(parsed.divorceDate)
   161→          : undefined;
   162→
   163→        // Create bidirectional SPOUSE relationships
   164→        relationships.push({
   165→          id: generateId(),
   166→          personId: husbandId,
   167→          relatedPersonId: wifeId,
   168→          type: "SPOUSE",
   169→          marriageDate,
   170→          divorceDate,
   171→          isActive: !divorceDate,
   172→        });
   173→
   174→        relationships.push({
   175→          id: generateId(),
   176→          personId: wifeId,
   177→          relatedPersonId: husbandId,
   178→          type: "SPOUSE",
   179→          marriageDate,
   180→          divorceDate,
   181→          isActive: !divorceDate,
   182→        });
   183→      }
   184→
   185→      // Handle same-sex couples - both parents recorded as spouses
   186→      if (parsed.husband && !parsed.wife && parsed.children.length > 0) {
   187→        // Check if there's another family with same husband to infer second spouse
   188→        const otherFamily = gedcomFile.families.find(
   189→          (f) =>
   190→            f.id !== record.id &&
   191→            (this.parser.parseFamily(f).husband === parsed.husband ||
   192→              this.parser.parseFamily(f).wife === parsed.husband)
   193→        );
   194→        if (otherFamily) {
   195→          const otherParsed = this.parser.parseFamily(otherFamily);
   196→          const secondPartner = otherParsed.wife || otherParsed.husband;
   197→          if (secondPartner && secondPartner !== parsed.husband) {
   198→            const husbandId = idMap.get(parsed.husband);
   199→            const secondId = idMap.get(secondPartner);
   200→            if (husbandId && secondId) {
   201→              relationships.push({
   202→                id: generateId(),
   203→                personId: husbandId,
   204→                relatedPersonId: secondId,
   205→                type: "SPOUSE",
   206→                isActive: true,
   207→              });
   208→              relationships.push({
   209→                id: generateId(),
   210→                personId: secondId,
   211→                relatedPersonId: husbandId,
   212→                type: "SPOUSE",
   213→                isActive: true,
   214→              });
   215→            }
   216→          }
   217→        }
   218→      }
   219→
   220→      // Create parent-child relationships
   221→      for (const childId of parsed.children) {
   222→        const childVamsaId = idMap.get(childId);
   223→
   224→        if (!childVamsaId) {
   225→          if (!options?.ignoreMissingReferences) {
   226→            errors.push({
   227→              type: "broken_reference",
   228→              source: "FAM",
   229→              id: parsed.id,
   230→              field: "CHIL",
   231→              message: `Broken child reference in family ${parsed.id}: ${childId}`,
   232→            });
   233→          }
   234→          continue;
   235→        }
   236→
   237→        // PARENT relationships (from parent to child)
   238→        if (parsed.husband) {
   239→          const husbandId = idMap.get(parsed.husband);
   240→          if (husbandId) {
   241→            relationships.push({
   242→              id: generateId(),
   243→              personId: husbandId,
   244→              relatedPersonId: childVamsaId,
   245→              type: "PARENT",
   246→              isActive: true,
   247→            });
   248→          }
   249→        }
   250→
   251→        if (parsed.wife) {
   252→          const wifeId = idMap.get(parsed.wife);
   253→          if (wifeId) {
   254→            relationships.push({
   255→              id: generateId(),
   256→              personId: wifeId,
   257→              relatedPersonId: childVamsaId,
   258→              type: "PARENT",
   259→              isActive: true,
   260→            });
   261→          }
   262→        }
   263→
   264→        // CHILD relationships (from child to parents)
   265→        if (parsed.husband) {
   266→          const husbandId = idMap.get(parsed.husband);
   267→          if (husbandId) {
   268→            relationships.push({
   269→              id: generateId(),
   270→              personId: childVamsaId,
   271→              relatedPersonId: husbandId,
   272→              type: "CHILD",
   273→              isActive: true,
   274→            });
   275→          }
   276→        }
   277→
   278→        if (parsed.wife) {
   279→          const wifeId = idMap.get(parsed.wife);
   280→          if (wifeId) {
   281→            relationships.push({
   282→              id: generateId(),
   283→              personId: childVamsaId,
   284→              relatedPersonId: wifeId,
   285→              type: "CHILD",
   286→              isActive: true,
   287→            });
   288→          }
   289→        }
   290→      }
   291→    }
   292→
   293→    return {
   294→      people,
   295→      relationships,
   296→      errors,
   297→      warnings,
   298→    };
   299→  }
   300→
   301→  /**
   302→   * Convert Vamsa data to GEDCOM format
   303→   */
   304→  mapToGedcom(
   305→    people: VamsaPerson[],
   306→    relationships: VamsaRelationship[]
   307→  ): { individuals: GedcomIndividualData[]; families: GedcomFamilyData[] } {
   308→    const individuals: GedcomIndividualData[] = [];
   309→    const families: GedcomFamilyData[] = [];
   310→
   311→    // Create ID to xref mapping
   312→    const idToXref = new Map<string, string>();
   313→    let individualsIndex = 1;
   314→
   315→    for (const person of people) {
   316→      if (person.id) {
   317→        idToXref.set(person.id, `@I${individualsIndex}@`);
   318→        individualsIndex++;
   319→      }
   320→    }
   321→
   322→    // Create individuals
   323→    for (const person of people) {
   324→      if (!person.id) continue;
   325→
   326→      const xref = idToXref.get(person.id);
   327→      if (!xref) continue;
   328→
   329→      const name = this.formatName(person.firstName, person.lastName);
   330→      const sex = this.mapGender(person.gender);
   331→
   332→      const individual: GedcomIndividualData = {
   333→        xref,
   334→        name,
   335→        sex,
   336→        birthDate: person.dateOfBirth
   337→          ? this.formatToGedcomDate(person.dateOfBirth)
   338→          : undefined,
   339→        birthPlace: person.birthPlace,
   340→        deathDate: person.dateOfPassing
   341→          ? this.formatToGedcomDate(person.dateOfPassing)
   342→          : undefined,
   343→        occupation: person.profession,
   344→        notes: person.bio ? [person.bio] : [],
   345→        familiesAsSpouse: [],
   346→        familiesAsChild: [],
   347→      };
   348→
   349→      individuals.push(individual);
   350→    }
   351→
   352→    // Build family structures from relationships
   353→    const familyMap = new Map<
   354→      string,
   355→      {
   356→        spouses: [string, string] | [string] | undefined;
   357→        children: string[];
   358→        marriages: Map<string, { marriageDate?: Date; divorceDate?: Date }>;
   359→      }
   360→    >();
   361→
   362→    // Group relationships by family units
   363→    for (const rel of relationships) {
   364→      if (rel.type === "SPOUSE") {
   365→        // Find or create family for this couple
   366→        let familyKey = `${rel.personId}-${rel.relatedPersonId}`;
   367→        let reverseKey = `${rel.relatedPersonId}-${rel.personId}`;
   368→
   369→        // Check if we already have this couple in reverse order
   370→        if (familyMap.has(reverseKey) && !familyMap.has(familyKey)) {
   371→          familyKey = reverseKey;
   372→        }
   373→
   374→        if (!familyMap.has(familyKey)) {
   375→          familyMap.set(familyKey, {
   376→            spouses: [rel.personId, rel.relatedPersonId] as [string, string],
   377→            children: [],
   378→            marriages: new Map(),
   379→          });
   380→        }
   381→
   382→        const family = familyMap.get(familyKey);
   383→        if (family && rel.marriageDate) {
   384→          const key = `${rel.personId}-${rel.relatedPersonId}`;
   385→          family.marriages.set(key, {
   386→            marriageDate: rel.marriageDate,
   387→            divorceDate: rel.divorceDate,
   388→          });
   389→        }
