    15→} from "@/actions/gedcom";
    16→
    17→interface GedcomImportPreviewProps {
    18→  result: ValidateGedcomResult;
    19→  file: File;
    20→  onReset: () => void;
    21→}
    22→
    23→async function performImport(file: File): Promise<ImportGedcomResult> {
    24→  const formData = new FormData();
    25→  formData.append("file", file);
    26→  return importGedcom(formData);
    27→}
    28→
    29→export function GedcomImportPreview({
    30→  result,
    31→  file,
    32→  onReset,
    33→}: GedcomImportPreviewProps) {
    34→  const { toast } = useToast();
    35→  const router = useRouter();
    36→  const [isImporting, setIsImporting] = useState(false);
    37→
    38→  const mutation = useMutation({
    39→    mutationFn: performImport,
    40→    onSuccess: (data) => {
    41→      if (data.success) {
    42→        toast({
    43→          title: "Import Successful",
    44→          description: data.message,
    45→        });
    46→        router.refresh();
    47→        // Auto-close after a short delay
    48→        setTimeout(() => {
    49→          onReset();
    50→        }, 2000);
    51→      } else {
    52→        toast({
    53→          title: "Import Failed",
    54→          description: data.message,
    55→          variant: "destructive",
    56→        });
    57→      }
    58→    },
    59→    onError: (error: Error) => {
    60→      toast({
    61→        title: "Import Error",
    62→        description: error.message,
    63→        variant: "destructive",
    64→      });
    65→    },
    66→    onSettled: () => {
    67→      setIsImporting(false);
    68→    },
    69→  });
    70→
    71→  const handleImport = () => {
    72→    setIsImporting(true);
    73→    mutation.mutate(file);
    74→  };
    75→
    76→  const hasErrors = result.preview?.errors && result.preview.errors.length > 0;
    77→  const errorCount =
    78→    result.preview?.errors?.filter(
    79→      (e) => e.type === "validation_error" || e.type === "mapping_error"
    80→    ).length || 0;
    81→  const warningCount =
    82→    result.preview?.errors?.filter(
    83→      (e) => e.type === "validation_warning" || e.type === "warning"
    84→    ).length || 0;
    85→
    86→  return (
    87→    <div className="space-y-6">
    88→      <Card>
    89→        <CardHeader>
    90→          <CardTitle>Import Preview</CardTitle>
    91→        </CardHeader>
    92→        <CardContent className="space-y-4">
    93→          <p>
    94→            Validation complete. Review the data to be imported from{" "}
    95→            <span className="font-semibold">{file.name}</span>.
    96→          </p>
    97→          <div className="grid grid-cols-2 gap-4">
    98→            <div className="rounded-lg border p-4">
    99→              <div className="text-sm text-muted-foreground">People</div>
   100→              <div className="text-2xl font-bold">
   101→                {result.preview?.peopleCount || 0}
   102→              </div>
   103→            </div>
   104→            <div className="rounded-lg border p-4">
   105→              <div className="text-sm text-muted-foreground">Families</div>
   106→              <div className="text-2xl font-bold">
   107→                {result.preview?.familiesCount || 0}
   108→              </div>
   109→            </div>
   110→          </div>
   111→        </CardContent>
   112→      </Card>
   113→
   114→      {result.valid && !hasErrors ? (
   115→        <Alert>
   116→          <CheckCircle className="h-4 w-4" />
   117→          <AlertTitle>Ready to Import</AlertTitle>
   118→          <AlertDescription>
   119→            The GEDCOM file is valid and ready to be imported.
   120→          </AlertDescription>
   121→        </Alert>
   122→      ) : !result.valid ? (
   123→        <Alert variant="destructive">
   124→          <AlertCircle className="h-4 w-4" />
   125→          <AlertTitle>Validation Failed</AlertTitle>
   126→          <AlertDescription>
   127→            The GEDCOM file has critical errors that prevent import. Please fix
   128→            these issues and try again.
   129→          </AlertDescription>
   130→        </Alert>
   131→      ) : (
   132→        <Alert>
   133→          <AlertTriangle className="h-4 w-4" />
   134→          <AlertTitle>Warnings Detected</AlertTitle>
   135→          <AlertDescription>
   136→            The file has some warnings but can still be imported. Review the
   137→            issues below.
   138→          </AlertDescription>
   139→        </Alert>
   140→      )}
   141→
   142→      {hasErrors && (
   143→        <Card>
   144→          <CardHeader>
   145→            <CardTitle>
   146→              Validation Issues ({errorCount} errors, {warningCount} warnings)
   147→            </CardTitle>
   148→          </CardHeader>
   149→          <CardContent>
   150→            <div className="max-h-60 space-y-2 overflow-auto">
   151→              {result.preview?.errors?.map((error, i) => (
   152→                <div
   153→                  key={i}
   154→                  className={`rounded-lg border p-3 text-sm ${
   155→                    error.type === "validation_error" ||
   156→                    error.type === "mapping_error"
